mapper.select:
select 
from biz_stock_warning w


        and w.warning_type = #{warningType}


        and w.handle_status = #{handleStatus}


        and w.book_id = #{bookId}


        and w.isbn = #{isbn}


        and w.title like concat('%', #{title}, '%')


        and w.create_time >= #{params.beginTime}


        and w.create_time <= #{params.endTime}


order by w.warning_id desc
